import{_ as n,o as s,c as t,a2 as e}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"什么是 AI Agent？","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/01-agent-basics/what-is-an-agent.md","filePath":"zh/learn/01-agent-basics/what-is-an-agent.md","lastUpdated":1792545482000}'),p={name:"zh/learn/01-agent-basics/what-is-an-agent.md"};function l(i,a,o,d,r,h){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="什么是-ai-agent" tabindex="-1">什么是 AI Agent？ <a class="header-anchor" href="#什么是-ai-agent" aria-label="Permalink to &quot;什么是 AI Agent？&quot;">​</a></h1><h2 id="一、从聊天到执行任务" tabindex="-1">一、从聊天到执行任务 <a class="header-anchor" href="#一、从聊天到执行任务" aria-label="Permalink to &quot;一、从聊天到执行任务&quot;">​</a></h2><p>我们平时使用 AI，最常见的方式是提问，然后等待回答。</p><p>例如：</p><blockquote><p>帮我分析一下最近的 AI 行业动态。</p></blockquote><p>普通的大模型应用可以根据已有知识生成分析。如果没有接入搜索工具，它可能无法获取最新的信息。</p><p>现在，我们把任务换成：</p><blockquote><p>搜索最近一周的 AI 行业新闻，筛选出最值得关注的 5 条，阅读原文，比较不同来源的观点，最后生成一份简报。</p></blockquote><p>要完成这个任务，系统可能需要：</p><ol><li>搜索相关新闻。</li><li>获取网页内容。</li><li>判断信息是否相关。</li><li>比较不同来源的观点。</li><li>发现信息不足时继续搜索。</li><li>整理结果并生成简报。</li></ol><p>这已经不只是生成一段文字，而是一个包含多个步骤的任务执行过程。</p><p><strong>AI Agent 的核心特征，是围绕目标，结合模型判断、工具调用和执行反馈，完成一系列任务。</strong></p><h2 id="二、llm、工作流与-agent-有什么区别" tabindex="-1">二、LLM、工作流与 Agent 有什么区别？ <a class="header-anchor" href="#二、llm、工作流与-agent-有什么区别" aria-label="Permalink to &quot;二、LLM、工作流与 Agent 有什么区别？&quot;">​</a></h2><h3 id="_1-llm-负责理解与生成" tabindex="-1">1. LLM：负责理解与生成 <a class="header-anchor" href="#_1-llm-负责理解与生成" aria-label="Permalink to &quot;1. LLM：负责理解与生成&quot;">​</a></h3><p>LLM（Large Language Model，大语言模型）能够理解输入、生成文本、分析信息，并根据上下文提出建议。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提问</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>大语言模型</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>生成回答</span></span></code></pre></div><p>模型可以解释如何查询天气，但如果没有连接天气服务，就不一定能够获取实时天气。</p><p>它可以生成 SQL 语句，但不代表已经连接数据库并执行了查询。</p><p>因此，需要区分两件事：</p><ul><li><strong>知道怎么做</strong>：模型生成了方法或操作建议。</li><li><strong>实际做了什么</strong>：程序执行了操作，并获得了结果。</li></ul><h3 id="_2-工作流-按照预定步骤执行" tabindex="-1">2. 工作流：按照预定步骤执行 <a class="header-anchor" href="#_2-工作流-按照预定步骤执行" aria-label="Permalink to &quot;2. 工作流：按照预定步骤执行&quot;">​</a></h3><p>工作流（Workflow）按照预先定义的规则执行任务。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取文章</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>提取正文</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>生成摘要</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>保存到数据库</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>发送通知</span></span></code></pre></div><p>每一步的执行顺序主要由程序决定。</p><p>工作流的优点是结构清晰、容易测试、执行过程相对可预测。</p><p>如果任务步骤固定，通常没有必要为了使用 AI 而引入复杂的 Agent。</p><h3 id="_3-agent-根据任务和反馈决定下一步" tabindex="-1">3. Agent：根据任务和反馈决定下一步 <a class="header-anchor" href="#_3-agent-根据任务和反馈决定下一步" aria-label="Permalink to &quot;3. Agent：根据任务和反馈决定下一步&quot;">​</a></h3><p>Agent 通常会让模型参与下一步行动的选择。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收研究任务</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>分析任务目标</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>调用搜索工具</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>获取搜索结果</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>判断信息是否充分</span></span>
<span class="line"><span>   ┌─┴─────┐</span></span>
<span class="line"><span>   │       │</span></span>
<span class="line"><span> 不充分   已充分</span></span>
<span class="line"><span>   │       │</span></span>
<span class="line"><span>继续搜索  生成报告</span></span></code></pre></div><p>Agent 可以根据实际执行结果调整后续行动，而不是只能沿着一条固定路径执行。</p><p>不过，Agent 并不一定比工作流更好。</p><p>如果任务简单、步骤固定，使用普通程序或工作流往往更可靠、更便宜，也更容易调试。</p><h3 id="三者对比" tabindex="-1">三者对比 <a class="header-anchor" href="#三者对比" aria-label="Permalink to &quot;三者对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>LLM 应用</th><th>工作流</th><th>Agent</th></tr></thead><tbody><tr><td>核心能力</td><td>理解与生成</td><td>按规则执行步骤</td><td>根据目标选择行动</td></tr><tr><td>步骤安排</td><td>通常以单次调用为主</td><td>主要由程序预先定义</td><td>可以根据结果动态调整</td></tr><tr><td>工具调用</td><td>可以支持</td><td>可以支持</td><td>通常用于完成任务</td></tr><tr><td>执行循环</td><td>通常较少</td><td>由流程定义</td><td>可以根据反馈反复执行</td></tr><tr><td>可预测性</td><td>取决于模型与任务</td><td>通常较高</td><td>受模型决策与环境影响</td></tr><tr><td>适用场景</td><td>问答、总结、改写</td><td>固定业务流程</td><td>需要动态决策的多步骤任务</td></tr></tbody></table><p>这些分类不是绝对的。一个系统可以同时包含 LLM、工作流和 Agent。</p><h2 id="三、agent-的基本组成" tabindex="-1">三、Agent 的基本组成 <a class="header-anchor" href="#三、agent-的基本组成" aria-label="Permalink to &quot;三、Agent 的基本组成&quot;">​</a></h2><p>一个常见的 Agent 系统，可以抽象为以下几个部分。</p><h3 id="_1-模型-model" tabindex="-1">1. 模型（Model） <a class="header-anchor" href="#_1-模型-model" aria-label="Permalink to &quot;1. 模型（Model）&quot;">​</a></h3><p>负责理解任务、分析上下文、选择工具，以及根据执行结果决定下一步。</p><p>模型本身不会自动获得操作系统、数据库或网络的访问权限。这些能力需要由外部程序提供。</p><h3 id="_2-指令与目标-instructions-goal" tabindex="-1">2. 指令与目标（Instructions / Goal） <a class="header-anchor" href="#_2-指令与目标-instructions-goal" aria-label="Permalink to &quot;2. 指令与目标（Instructions / Goal）&quot;">​</a></h3><p>告诉 Agent 要完成什么、遵守哪些约束，以及什么样的结果才算完成。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：生成一份 AI 行业日报。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>约束：</span></span>
<span class="line"><span>- 优先使用最近 24 小时的信息。</span></span>
<span class="line"><span>- 尽量核对多个独立来源。</span></span>
<span class="line"><span>- 无法确认的信息必须标记。</span></span>
<span class="line"><span>- 最多执行 10 次工具调用。</span></span>
<span class="line"><span>- 最终输出 5 条重点新闻。</span></span></code></pre></div><p>明确目标和约束，可以减少任务偏离和无效调用。</p><h3 id="_3-工具-tools" tabindex="-1">3. 工具（Tools） <a class="header-anchor" href="#_3-工具-tools" aria-label="Permalink to &quot;3. 工具（Tools）&quot;">​</a></h3><p>为 Agent 提供与外部世界交互的能力。</p><p>常见工具包括：</p><ul><li>搜索引擎。</li><li>HTTP API。</li><li>数据库查询。</li><li>文件读取与写入。</li><li>代码执行环境。</li><li>业务系统接口。</li><li>其他 Agent 提供的服务。</li></ul><p>工具调用的原理将在下一篇详细介绍。</p><h3 id="_4-上下文与记忆-context-memory" tabindex="-1">4. 上下文与记忆（Context / Memory） <a class="header-anchor" href="#_4-上下文与记忆-context-memory" aria-label="Permalink to &quot;4. 上下文与记忆（Context / Memory）&quot;">​</a></h3><p>帮助 Agent 利用当前任务信息和历史结果。</p><p>例如：</p><ul><li>当前任务的目标。</li><li>已经搜索过的新闻。</li><li>已经调用过的工具。</li><li>前几步执行的结果。</li><li>用户明确提供的偏好。</li></ul><p>需要注意，<strong>上下文不等于长期记忆</strong>。</p><p>对话中保留的信息、数据库中的历史记录和独立的记忆系统，是不同的实现方式。</p><h3 id="_5-执行循环-execution-loop" tabindex="-1">5. 执行循环（Execution Loop） <a class="header-anchor" href="#_5-执行循环-execution-loop" aria-label="Permalink to &quot;5. 执行循环（Execution Loop）&quot;">​</a></h3><p>负责把模型决策、工具执行和结果反馈串联起来。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收任务</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>构造模型输入</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>模型决定下一步</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>是否需要调用工具？</span></span>
<span class="line"><span>   ├── 是 → 检查权限 → 执行工具 → 返回结果</span></span>
<span class="line"><span>   │                          ↑          │</span></span>
<span class="line"><span>   │                          └──────────┘</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   └── 否 → 输出最终结果</span></span></code></pre></div><p>实际工程中，还需要设置最大迭代次数、超时、错误处理和人工介入条件。</p><h2 id="四、一个完整的-agent-示例" tabindex="-1">四、一个完整的 Agent 示例 <a class="header-anchor" href="#四、一个完整的-agent-示例" aria-label="Permalink to &quot;四、一个完整的 Agent 示例&quot;">​</a></h2><p>假设用户提出任务：</p><blockquote><p>帮我比较三家公司的公开产品信息，整理一份简短的对比报告。</p></blockquote><p>Agent 可能按以下步骤执行：</p><ol><li>分析任务，确定需要比较的公司和维度。</li><li>调用搜索工具，获取公开资料。</li><li>调用网页读取工具，获取具体产品信息。</li><li>检查资料是否完整，以及不同来源之间是否存在冲突。</li><li>必要时再次搜索。</li><li>对信息进行归纳。</li><li>生成对比报告，并注明信息来源。</li></ol><p>整个过程中的职责分工如下：</p><table tabindex="0"><thead><tr><th>参与者</th><th>职责</th></tr></thead><tbody><tr><td>用户</td><td>提出目标和约束</td></tr><tr><td>LLM</td><td>理解任务、提出行动建议、整理结果</td></tr><tr><td>Agent 程序</td><td>控制执行流程、调度工具、管理状态</td></tr><tr><td>工具</td><td>执行搜索、读取网页等具体操作</td></tr><tr><td>外部服务</td><td>返回实际数据或执行结果</td></tr></tbody></table><p>这里最重要的一点是：</p><p><strong>模型提出行动建议，程序决定如何执行，工具返回实际结果。</strong></p><h2 id="五、agent-不是什么" tabindex="-1">五、Agent 不是什么？ <a class="header-anchor" href="#五、agent-不是什么" aria-label="Permalink to &quot;五、Agent 不是什么？&quot;">​</a></h2><h3 id="误区-1-接入大模型就是-agent" tabindex="-1">误区 1：接入大模型就是 Agent <a class="header-anchor" href="#误区-1-接入大模型就是-agent" aria-label="Permalink to &quot;误区 1：接入大模型就是 Agent&quot;">​</a></h3><p>不一定。</p><p>一个只调用模型生成文本的应用，可以是普通 LLM 应用。</p><p>Agent 通常还包含目标驱动的行动选择、工具执行与结果反馈。</p><h3 id="误区-2-agent-一定需要复杂框架" tabindex="-1">误区 2：Agent 一定需要复杂框架 <a class="header-anchor" href="#误区-2-agent-一定需要复杂框架" aria-label="Permalink to &quot;误区 2：Agent 一定需要复杂框架&quot;">​</a></h3><p>不需要。</p><p>一个简单的 Agent 可以由普通 Python 或 Java 程序实现。</p><p>框架的价值主要在于减少重复开发、提供标准抽象，以及帮助组织更复杂的执行流程。</p><h3 id="误区-3-agent-越自主越好" tabindex="-1">误区 3：Agent 越自主越好 <a class="header-anchor" href="#误区-3-agent-越自主越好" aria-label="Permalink to &quot;误区 3：Agent 越自主越好&quot;">​</a></h3><p>不一定。</p><p>如果任务涉及删除数据、发送消息、修改生产环境或使用真实资金，完全自主执行可能带来严重后果。</p><p>自主度应该与任务风险、可逆性和授权范围相匹配。</p><h3 id="误区-4-agent-能完成任务-就代表结果正确" tabindex="-1">误区 4：Agent 能完成任务，就代表结果正确 <a class="header-anchor" href="#误区-4-agent-能完成任务-就代表结果正确" aria-label="Permalink to &quot;误区 4：Agent 能完成任务，就代表结果正确&quot;">​</a></h3><p>不成立。</p><p>Agent 可能使用过时数据、调用错误工具、误解工具结果，甚至在失败后错误地报告任务成功。</p><p>因此，重要任务需要结果校验、日志记录和失败恢复机制。</p><h2 id="六、什么时候应该使用-agent" tabindex="-1">六、什么时候应该使用 Agent？ <a class="header-anchor" href="#六、什么时候应该使用-agent" aria-label="Permalink to &quot;六、什么时候应该使用 Agent？&quot;">​</a></h2><p>可以参考以下判断。</p><p><strong>适合考虑 Agent 的场景：</strong></p><ul><li>任务需要根据中间结果动态决定下一步。</li><li>任务需要组合多个不同的工具。</li><li>输入与执行路径存在较大变化。</li><li>可以定义明确的完成条件与执行边界。</li><li>能够验证结果，并承担合理的执行成本。</li></ul><p><strong>不一定需要 Agent 的场景：</strong></p><ul><li>只有一次简单问答。</li><li>任务步骤固定且规则明确。</li><li>对结果确定性要求很高。</li><li>调用模型带来的成本明显高于实际收益。</li><li>系统无法安全地限制工具权限。</li></ul><p>工程实践中，可以先用确定性的工作流解决问题，再在确实需要动态决策的环节引入 Agent。</p><h2 id="七、小结" tabindex="-1">七、小结 <a class="header-anchor" href="#七、小结" aria-label="Permalink to &quot;七、小结&quot;">​</a></h2><p>理解 Agent，可以记住下面这句话：</p><p><strong>LLM 负责理解与生成，工具负责执行具体操作，Agent 程序负责把目标、决策、行动和反馈组织起来。</strong></p><p>Agent 的价值不只是让 AI 回答得更好，而是让 AI 能够在实际环境中完成多步骤任务。</p><p>但一旦系统开始执行真实操作，就必须同时考虑权限、成本、错误处理和安全边界。</p><h2 id="下一篇" tabindex="-1">下一篇 <a class="header-anchor" href="#下一篇" aria-label="Permalink to &quot;下一篇&quot;">​</a></h2><p><a href="./tool-calling">工具调用：Agent 如何接触外部世界</a></p>`,103)])])}const u=n(p,[["render",l]]);export{g as __pageData,u as default};
